    tile = (h - k + 1) // k
    stride = tile + 1
    out = [row[:] for row in grid]

    # Locate the masked tile row/column (the 3 band runs across the full grid).
    masked_rows = [r for r in range(h) if all(v == 3 for v in grid[r])]
    masked_cols = [c for c in range(w) if all(grid[r][c] == 3 for r in range(h))]
    row_band = masked_rows[0] // stride if masked_rows else None
    col_band = masked_cols[0] // stride if masked_cols else None

    # Learn the repeated 2-pattern from the unmasked, nonempty tiles; the
    # exceptional tile is noise and is removed in the demonstrations.
    from collections import Counter
    patterns = []
    for tr in range(k):
        for tc in range(k):
            if tr == row_band or tc == col_band:
